import java.util.Scanner;

public class ElectricBill {
    // Data members
    private String n;
    private int units;
    private double bill;

    // Method to accept customer details
    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter customer name: ");
        n = sc.nextLine();
        System.out.print("Enter units consumed: ");
        units = sc.nextInt();
    }

    // Method to calculate electricity bill according to slab tariff
    public void calculate() {
        if (units <= 100) {
            bill = units * 1.25;
        } else if (units <= 300) {
            bill = (100 * 1.25) + ((units - 100) * 1.50);
        } else {
            double basicBill = (100 * 1.25) + (200 * 1.50) + ((units - 300) * 1.80);
            double surcharge = 0.025 * basicBill; // 2.5% surcharge
            bill = basicBill + surcharge;
        }
    }

    // Method to display billing details
    public void print() {
        System.out.println("\n========================================");
        System.out.println("       ELECTRICITY CONSUMER INVOICE     ");
        System.out.println("========================================");
        System.out.println("Customer Name    : " + n);
        System.out.println("Units Consumed   : " + units);
        System.out.printf("Total Bill Amount: Rs. %.2f\n", bill);
        System.out.println("========================================");
    }

    // Main method to test the class
    public static void main(String[] args) {
        ElectricBill consumer = new ElectricBill();
        consumer.accept();
        consumer.calculate();
        consumer.print();
    }
}
```

