import java.util.Scanner;

public class BinarySearchDemo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] arr = new int[15];

        System.out.println("Enter 15 integers in strictly ascending order:");
        for (int i = 0; i < 15; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.print("Enter the integer to search for: ");
        int key = sc.nextInt();

        int low = 0;
        int high = arr.length - 1;
        int pos = -1;

        // Binary Search Algorithm
        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (arr[mid] == key) {
                pos = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1; // search in right half
            } else {
                high = mid - 1; // search in left half
            }
        }

        if (pos != -1) {
            System.out.println("Search successful. Element found at index: " + pos + " (Position: " + (pos + 1) + ")");
        } else {
            System.out.println("Search unsuccessful. Element not present in the array.");
        }

        sc.close();
    }
}
```

