import java.util.Scanner;

public class SentenceAnalysis {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence terminated with a period (.):");
        String sentence = sc.nextLine().trim();

        // Remove terminating period if present
        if (sentence.endsWith(".")) {
            sentence = sentence.substring(0, sentence.length() - 1).trim();
        }

        String upperStr = sentence.toUpperCase();

        // 1. Count vowels
        int vowelCount = 0;
        for (int i = 0; i < upperStr.length(); i++) {
            char ch = upperStr.charAt(i);
            if (ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U') {
                vowelCount++;
            }
        }

        // 2. Split words and count words
        String[] words = upperStr.split("\\s+");
        int wordCount = words.length;

        // 3. Reverse order of words
        StringBuilder reversedSentence = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            reversedSentence.append(words[i]);
            if (i > 0) {
                reversedSentence.append(" ");
            }
        }

        System.out.println("\n--- Analysis Report ---");
        System.out.println("Total Words: " + wordCount);
        System.out.println("Total Vowels: " + vowelCount);
        System.out.println("Reversed Words: " + reversedSentence.toString());

        sc.close();
    }
}
```

