import java.util.Scanner;

public class SpecialNumberCheck {
    // Helper method to compute factorial of a single digit
    public static int factorial(int digit) {
        int fact = 1;
        for (int i = 1; i <= digit; i++) {
            fact *= i;
        }
        return fact;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer number to check: ");
        int num = sc.nextInt();

        if (num <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        int temp = num;
        int sumFactorials = 0;

        // Extract each digit and add factorial of that digit
        while (temp > 0) {
            int d = temp % 10;
            sumFactorials += factorial(d);
            temp /= 10;
        }

        // Check equality
        if (sumFactorials == num) {
            System.out.println(num + " is a SPECIAL NUMBER.");
        } else {
            System.out.println(num + " is NOT a Special Number.");
        }

        sc.close();
    }
}
```

