import java.util.Scanner;

public class MatrixDiagonalsSymmetry {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 4;
        int[][] mat = new int[n][n];

        System.out.println("Enter elements for a 4x4 matrix (16 integers):");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = sc.nextInt();
            }
        }

        // Display Matrix
        System.out.println("\nInput Matrix:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(mat[i][j] + "\t");
            }
            System.out.println();
        }

        int leftDiagonalSum = 0;
        int rightDiagonalSum = 0;
        boolean isSymmetric = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Left Diagonal condition: i == j
                if (i == j) {
                    leftDiagonalSum += mat[i][j];
                }
                // Right Diagonal condition: i + j == n - 1
                if (i + j == n - 1) {
                    rightDiagonalSum += mat[i][j];
                }
                // Symmetry test: mat[i][j] must equal mat[j][i]
                if (mat[i][j] != mat[j][i]) {
                    isSymmetric = false;
                }
            }
        }

        System.out.println("\nLeft (Principal) Diagonal Sum = " + leftDiagonalSum);
        System.out.println("Right (Secondary) Diagonal Sum = " + rightDiagonalSum);
        if (isSymmetric) {
            System.out.println("The given matrix is SYMMETRIC.");
        } else {
            System.out.println("The given matrix is NOT SYMMETRIC.");
        }

        sc.close();
    }
}
```

